const MAX_CONTRACT_REPAIR_ATTEMPTS = 2;

function scheduleFollowUpPrompts({
  prisma,
  messageId,
  chat,
  assistantContent,
  files,
}: {
  prisma: ReturnType<typeof getPrisma>;
  messageId: string;
  chat: Parameters<typeof generateFollowUpPrompts>[0]["chat"];
  assistantContent: string;
  files: GeneratedFile[];
}) {
  after(async () => {
    const prompts = await generateFollowUpPrompts({
      chat,
      assistantContent,
      files,
    });
    await saveMessageFollowUpPrompts(prisma, messageId, prompts);
  });
}

type ContractRepairMetadata = {
  kind: "contract_repair";
  chargeCredits: false;
  rootGenerationRunId: string;
  sourceRunId: string;
  attempt: number;
  maxAttempts: number;
  draftFiles: GeneratedFile[];
  diagnostics: string[];
  usedAt: string | null;
};

function readContractRepairMetadata(value: unknown) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const metadata = value as Partial<ContractRepairMetadata>;
  if (
    metadata.kind !== "contract_repair" ||
    metadata.chargeCredits !== false ||
    typeof metadata.rootGenerationRunId !== "string" ||
    typeof metadata.sourceRunId !== "string" ||
    typeof metadata.attempt !== "number" ||
    typeof metadata.maxAttempts !== "number" ||
    !Array.isArray(metadata.draftFiles) ||
    !Array.isArray(metadata.diagnostics)
  ) {
    return null;
  }
  return metadata as ContractRepairMetadata;
}

function sanitizeContractDiagnostics(
  diagnostics: GeneratedFileDiagnostic[],
): string[] {
  return diagnostics
    .slice(0, 12)
    .map((diagnostic) =>
      `${diagnostic.path ? `${diagnostic.path}: ` : ""}${diagnostic.message}`
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 600),
    );
}

async function getGeneratedAppContractDiagnostics(
  prisma: ReturnType<typeof getPrisma>,
  chatId: string,
  files: GeneratedFile[],
) {
  const selectedBindings = await prisma.projectIntegration.findMany({
    where: { chatId },
    select: { providerId: true, config: true },
  });
  const diagnostics = validateSelectedApiUsage(
    files,
    selectedBindings.map((binding) => binding.providerId),
  );
  const readySupabaseBackends = selectedBindings.flatMap((binding) => {
    if (binding.providerId !== "supabase") return [];
    const backend = readSupabaseBackendState(binding.config);
    return backend?.status === "ready" ? [backend.plan] : [];
  });
  for (const plan of readySupabaseBackends) {
    if (
      plan.migrationChecksum ===
      getAuthenticatedTasksBackendPlan().migrationChecksum
    ) {
      diagnostics.push(
        ...(await validateAuthenticatedTasksGeneratedApp(files)),
      );
    } else {
      diagnostics.push(...validateSupabaseBackendGeneratedApp(files, plan));
    }
  }
  return diagnostics;
}

function contractViolationError(diagnostics: GeneratedFileDiagnostic[]) {
  return new Error(
    `SELECTED_API_CONTRACT_VIOLATION: ${sanitizeContractDiagnostics(
      diagnostics,
    ).join(" ")}`,
  );
}

function getAssistantMessageFiles(message: Message) {
  if (message?.role !== "assistant") return [];
  return getMessageGeneratedFiles(message);
}

function findSourceAssistantMessage(
  messages: Message[],
  sourceMessageId?: string,
) {
  const sourceMessage = sourceMessageId
    ? messages.find((message) => message.id === sourceMessageId)
    : messages
        .slice()
        .filter(
          (message) =>
            message.role === "assistant" &&
            getAssistantMessageFiles(message).length > 0,
        )
        .sort((a, b) => b.position - a.position)[0];

  return sourceMessage?.role === "assistant" &&
    getAssistantMessageFiles(sourceMessage).length > 0
    ? sourceMessage
    : null;
}

function getCheckpointMetadata(messages: Message[]) {
  const latestUserMessage = messages
    .filter((message) => message.role === "user")
    .sort((a, b) => b.position - a.position)[0];
  const metadata = latestUserMessage?.files as
    | RequestModeMetadata
    | null
    | undefined;
  const hasPreviousVersion = messages.some(
    (message) =>
      message.role === "assistant" &&
      getAssistantMessageFiles(message).length > 0,
  );

  if (metadata?.kind === "targeted_element_edit") {
    const target =
      metadata.selection?.ariaLabel ||
      metadata.selection?.text ||
      metadata.selection?.tagName;
    return {
      versionKind: "targeted_edit",
      changeSummary: `Changed selected ${String(target || "element")
        .trim()
        .slice(0, 48)}`,
    };
  }
  if (
    metadata?.kind === "preview_repair" ||
    metadata?.kind === "preview_repair_request"
  ) {
    return { versionKind: "repair", changeSummary: "Repaired preview" };
  }

  const request = latestUserMessage?.content
    .replace(/\s+/g, " ")
    .trim()
    .replace(
      /^(please\s+)?(build|create|make|update|change|add)\s+(me\s+)?/i,
      "",
    )
    .slice(0, 64);
  return {
    versionKind: hasPreviousVersion ? "edit" : "generation",
    changeSummary: request
      ? `${hasPreviousVersion ? "Updated" : "Built"} ${request}`
      : hasPreviousVersion
        ? "Updated app"
        : "Initial build",
  };
}

async function createChargeableEditRequestMessage({
  chatId,
  text,
  kind,
  sourceMessageId,
  selection,
}: {
  chatId: string;
  text: string;
  kind: "app_edit_request" | "targeted_element_edit";
  sourceMessageId?: string;
  selection?: PreviewElementSelection;
}) {
  const session = await getCurrentSession();

  if (!session) {
    throw new Error("You must be signed in to send messages");
  }

  const prisma = getPrisma();
  const chat = await findOwnedProjectWithMessages(chatId, session.user.id);
  if (!chat) notFound();

  const trimmedText = text.trim().slice(0, 8000);
  if (!trimmedText) {
    throw new Error("Edit request cannot be empty");
  }

  const sourceMessage = findSourceAssistantMessage(
    chat.messages,
    sourceMessageId,
  );

  if (!sourceMessage) {
    throw new Error("Edits require an existing generated version");
  }

  const creditCheck = await checkCreditAvailability({
    userId: session.user.id,
    modelId: chat.model,
  });

  if (!creditCheck.success) {
    if (creditCheck.error === "INSUFFICIENT_CREDITS") {
      throw new Error("INSUFFICIENT_CREDITS");
    }
    throw new Error("CREDIT_CHECK_FAILED");
  }

  const maxPosition =
    chat.messages.length > 0
      ? Math.max(...chat.messages.map((message) => message.position))
      : 0;
  const metadata: RequestModeMetadata = {
    kind,
    sourceMessageId: sourceMessage.id,
    chargeCredits: true,
    ...(selection ? { selection } : {}),
  };

  return await prisma.message.create({
    data: {
      role: "user",
      content: trimmedText,
      files: metadata,
      position: maxPosition + 1,
      chatId,
    },
  });
}

export async function createMessage(
  chatId: string,
  text: string,
  role: "assistant" | "user",
  files?: RawGeneratedFile[],
  options?: { creditHoldId?: string; generationRunId?: string },
) {
  // Check authentication
  const session = await getCurrentSession();

  if (!session) {
    throw new Error("You must be signed in to send messages");
  }

  const prisma = getPrisma();
  const chat = await findOwnedProjectWithMessages(chatId, session.user.id);
  if (!chat) notFound();

  const maxPosition =
    chat.messages.length > 0
      ? Math.max(...chat.messages.map((message) => message.position))
      : 0;

  // Follow-up user messages only reserve the right to start generation. Credits
  // are charged when the assistant response is successfully persisted.
  const isFollowUpUserMessage = role === "user" && chat.messages.length >= 2;

  if (isFollowUpUserMessage) {
    const creditCheck = await checkCreditAvailability({
      userId: session.user.id,
      modelId: chat.model,
    });

    if (!creditCheck.success) {
      if (creditCheck.error === "INSUFFICIENT_CREDITS") {
        throw new Error("INSUFFICIENT_CREDITS");
      }
      throw new Error("CREDIT_CHECK_FAILED");
    }
  }

  const normalizedFiles: GeneratedFile[] = files
    ? normalizeGeneratedFiles(files)
    : [];
  const assistantHasFiles = role === "assistant" && normalizedFiles.length > 0;
  const finalizedCode =
    assistantHasFiles && text.trim()
      ? finalizeGeneratedCodeFromText(text)
      : null;
  const designScores =
    finalizedCode?.ok && finalizedCode.designScores
      ? finalizedCode.designScores
      : null;
  if (assistantHasFiles) {
    const selectedApiDiagnostics = await getGeneratedAppContractDiagnostics(
      prisma,
      chatId,
      normalizedFiles,
    );

    if (selectedApiDiagnostics.length > 0) {
      if (options?.generationRunId) {
        await prisma.generationRun.updateMany({
          where: {
            id: options.generationRunId,
            chatId,
            userId: session.user.id,
          },
          data: {
            status: "recoverable",
            phase: "validation_repair",
            label: "Fixing generated app",
            errorMessage: "Generated app did not pass its required contract",
          },
        });
      }
      throw contractViolationError(selectedApiDiagnostics);
    }
  }
  const messageData = {
    role,
    content: text,
    files:
      normalizedFiles.length > 0
        ? JSON.parse(JSON.stringify(normalizedFiles))
        : null,
    position: maxPosition + 1,
    chatId,
    ...(role === "assistant" ? getCheckpointMetadata(chat.messages) : {}),
    ...(designScores
      ? { designScores: JSON.parse(JSON.stringify(designScores)) }
      : {}),
  };

  if (role === "assistant") {
    const newMessage = await prisma.$transaction(async (tx) => {
      const newMessage = await tx.message.create({
        data: messageData,
      });

      if (assistantHasFiles) {
        await tx.chat.update({
          where: { id: chatId },
          data: { hasCode: true },
        });
      }

      const creditCheck = await consumeCreditsForGeneration({
        client: tx,
        userId: session.user.id,
        modelId: chat.model,
        chatId,
        messageId: newMessage.id,
        description: `AI generation - ${chat.model}`,
        phase: "follow_up",
        status: "completed",
        creditHoldId: options?.creditHoldId,
        generatedText: text,
      });

      if (!creditCheck.success) {
        if (creditCheck.error === "INSUFFICIENT_CREDITS") {
          throw new Error("INSUFFICIENT_CREDITS");
        }
        throw new Error("CREDIT_CHECK_FAILED");
      }

      if (options?.generationRunId) {
        await tx.generationRun.updateMany({
          where: {
            id: options.generationRunId,
            chatId,
            userId: session.user.id,
            status: { in: ["running", "recoverable"] },
          },
          data: {
            status: "completed",
            assistantMessageId: newMessage.id,
            completedAt: new Date(),
            phase: "completed",
            label: "Saved",
            errorMessage: null,
          },
        });
      }

      return newMessage;
    });

    scheduleFollowUpPrompts({
      prisma,
      messageId: newMessage.id,
      chat,
      assistantContent: text,
      files: normalizedFiles,
    });

    return newMessage;
  }

  const newMessage = await prisma.$transaction(async (tx) => {
    const lockKey = `chat-user-message:${chatId}`;
    await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtextextended(${lockKey}, 0))`;
    const currentMessages = await tx.message.findMany({
      where: { chatId },
      orderBy: { position: "asc" },
    });
    for (const candidate of shouldAnswerWithoutCode(text)
      ? []
      : currentMessages) {
      const metadata = parseAgentMessageMetadata(candidate.files);
      if (
        metadata?.kind !== "agent_backend_setup_request" ||
        metadata.request.continuation.status !== "pending"
      ) {
        continue;
      }
      await tx.message.update({
        where: { id: candidate.id },
        data: {
          files: JSON.parse(
            JSON.stringify({
              ...metadata,
              request: {
                ...metadata.request,
                continuation: {
                  ...metadata.request.continuation,
                  status: "superseded",
                },
              },
            }),
          ),
        },
      });
    }
    const currentMaxPosition =
      currentMessages.length > 0
        ? Math.max(...currentMessages.map((message) => message.position))
        : 0;
    return tx.message.create({
      data: { ...messageData, position: currentMaxPosition + 1 },
    });
  });

  if (assistantHasFiles) {
    await prisma.chat.update({
      where: { id: chatId },
      data: { hasCode: true },
    });
  }

  return newMessage;
}

export async function saveStreamedAssistantMessage(
  chatId: string,
  text: string,
  files: RawGeneratedFile[],
  options?: { creditHoldId?: string; generationRunId?: string },
) {
  return createMessage(chatId, text, "assistant", files, options);
}

export async function releaseReservedCreditHold(holdId: string) {
  const session = await getCurrentSession();

  if (!session) {
    throw new Error("You must be signed in to release credits");
  }

  const prisma = getPrisma();
  const hold = await prisma.creditHold.findUnique({
    where: { id: holdId },
    select: { userId: true, status: true },
  });

  if (!hold || hold.userId !== session.user.id || hold.status !== "active") {
    return { success: true };
  }

  return releaseCreditHold({ holdId });
}

