export async function createPreviewRepairMessage(
  chatId: string,
  error: string,
  options?: { sourceMessageId?: string },
) {
  const session = await getCurrentSession();

  if (!session) {
    throw new Error("You must be signed in to request a repair");
  }

  const prisma = getPrisma();
  const chat = await findOwnedProjectWithMessages(chatId, session.user.id);
  if (!chat) notFound();

  const sourceMessage = options?.sourceMessageId
    ? chat.messages.find((message) => message.id === options.sourceMessageId)
    : chat.messages
        .slice()
        .reverse()
        .find(
          (message) =>
            message.role === "assistant" &&
            Array.isArray(message.files) &&
            message.files.length > 0,
        );
  const sourceFiles =
    sourceMessage?.role === "assistant"
      ? getMessageGeneratedFiles(sourceMessage)
      : [];
  if (options?.sourceMessageId && sourceMessage?.role !== "assistant") {
    throw new Error("Repair source version was not found");
  }

  const hasAnyGeneratedFiles = chat.messages.some(
    (message) =>
      message.role === "assistant" &&
      Array.isArray(message.files) &&
      message.files.length > 0,
  );

  if (!hasAnyGeneratedFiles || !sourceMessage || sourceFiles.length === 0) {
    throw new Error("Repairs require an existing generated version");
  }

  const maxPosition =
    chat.messages.length > 0
      ? Math.max(...chat.messages.map((message) => message.position))
      : 0;
  const trimmedError = error.trim().slice(0, 8000);
  const content = `The code is not working. Can you fix it? Here's the error:\n\n${trimmedError}`;

  return await prisma.message.create({
    data: {
      role: "user",
      content,
      files: {
        kind: "preview_repair",
        chargeCredits: false,
        sourceMessageId: sourceMessage.id,
        usedAt: null,
      },
      position: maxPosition + 1,
      chatId,
    },
  });
}

export async function createValidationRepairMessage(
  chatId: string,
  generationRunId: string,
  files: RawGeneratedFile[],
) {
  const session = await getCurrentSession();
  if (!session) {
    throw new Error("You must be signed in to repair generated code");
  }

  const prisma = getPrisma();
  const chat = await findOwnedProjectWithMessages(chatId, session.user.id);
  if (!chat) notFound();

  const sourceGenerationRun = await prisma.generationRun.findFirst({
    where: { id: generationRunId, chatId, userId: session.user.id },
    select: { messageId: true },
  });
  const sourceRequestMessage = sourceGenerationRun
    ? await prisma.message.findFirst({
        where: {
          id: sourceGenerationRun.messageId,
          chatId,
          role: "user",
        },
        select: { files: true },
      })
    : null;
  const sourceRequestMetadata = sourceRequestMessage?.files as
    | { registryFiles?: unknown }
    | null
    | undefined;
  const registryFiles = normalizeGeneratedFiles(
    parseStoredGeneratedFiles(sourceRequestMetadata?.registryFiles),
  );
  const normalizedFiles = normalizeGeneratedFiles([
    ...files,
    ...registryFiles,
  ]);
  const diagnostics = await getGeneratedAppContractDiagnostics(
    prisma,
    chatId,
    normalizedFiles,
  );
  if (diagnostics.length === 0) {
    throw new Error("Generated app no longer requires contract repair");
  }
  const sanitizedDiagnostics = sanitizeContractDiagnostics(diagnostics);

  const result = await prisma.$transaction(async (tx) => {
    const lockKey = `contract-repair:${chatId}`;
    await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtextextended(${lockKey}, 0))`;

    const sourceRun = await tx.generationRun.findFirst({
      where: { id: generationRunId, chatId, userId: session.user.id },
      select: {
        id: true,
        messageId: true,
        creditHoldId: true,
        status: true,
      },
    });
    if (!sourceRun) {
      throw new Error("Generation run was not found");
    }

    const sourceMessage = await tx.message.findFirst({
      where: { id: sourceRun.messageId, chatId, role: "user" },
      select: { files: true },
    });
    const sourceRepair = readContractRepairMetadata(sourceMessage?.files);
    const rootGenerationRunId =
      sourceRepair?.rootGenerationRunId ?? sourceRun.id;
    const rootRun =
      rootGenerationRunId === sourceRun.id
        ? sourceRun
        : await tx.generationRun.findFirst({
            where: {
              id: rootGenerationRunId,
              chatId,
              userId: session.user.id,
            },
            select: {
              id: true,
              messageId: true,
              creditHoldId: true,
              status: true,
            },
          });
    if (!rootRun) {
      throw new Error("Original generation run was not found");
    }

    const messages = await tx.message.findMany({
      where: { chatId, role: "user" },
      orderBy: { position: "asc" },
      select: { id: true, files: true, position: true },
    });
    const existingRepairs = messages.flatMap((message) => {
      const metadata = readContractRepairMetadata(message.files);
      return metadata?.rootGenerationRunId === rootGenerationRunId
        ? [{ message, metadata }]
        : [];
    });
    const duplicate = existingRepairs.find(
      ({ metadata }) => metadata.sourceRunId === sourceRun.id,
    );
    if (duplicate) {
      return {
        kind: "created" as const,
        id: duplicate.message.id,
        attempt: duplicate.metadata.attempt,
      };
    }

    if (existingRepairs.length >= MAX_CONTRACT_REPAIR_ATTEMPTS) {
      const completedAt = new Date();
      await tx.generationRun.updateMany({
        where: { id: { in: [rootRun.id, sourceRun.id] } },
        data: {
          status: "failed",
          phase: "validation_failed",
          label: "Generated app needs manual repair",
          errorMessage:
            "Automatic repair could not satisfy the generated app contract",
          completedAt,
        },
      });
      return {
        kind: "exhausted" as const,
        creditHoldId: rootRun.creditHoldId,
      };
    }

    const attempt = existingRepairs.length + 1;
    const metadata: ContractRepairMetadata = {
      kind: "contract_repair",
      chargeCredits: false,
      rootGenerationRunId,
      sourceRunId: sourceRun.id,
      attempt,
      maxAttempts: MAX_CONTRACT_REPAIR_ATTEMPTS,
      draftFiles: normalizedFiles,
      diagnostics: sanitizedDiagnostics,
      usedAt: null,
    };
    const allMessages = await tx.message.findMany({
      where: { chatId },
      select: { position: true },
    });
    const maxPosition = allMessages.reduce(
      (maximum, message) => Math.max(maximum, message.position),
      0,
    );
    const repairMessage = await tx.message.create({
      data: {
        role: "user",
        content: `Repair the generated app so it satisfies its required behavior and accessibility contract. Attempt ${attempt} of ${MAX_CONTRACT_REPAIR_ATTEMPTS}.`,
        files: JSON.parse(JSON.stringify(metadata)),
        position: maxPosition + 1,
        chatId,
      },
      select: { id: true },
    });
    await tx.generationRun.updateMany({
      where: { id: { in: [rootRun.id, sourceRun.id] } },
      data: {
        status: "recoverable",
        phase: "validation_repair",
        label: `Fixing generated app (${attempt}/${MAX_CONTRACT_REPAIR_ATTEMPTS})`,
        errorMessage: "Generated app did not pass its required contract",
      },
    });
    return { kind: "created" as const, id: repairMessage.id, attempt };
  });

  if (result.kind === "exhausted") {
    if (result.creditHoldId) {
      await releaseCreditHold({ holdId: result.creditHoldId });
    }
    throw new Error(
      "Automatic repair could not complete this app after two attempts. Retry the build or edit the generated app manually.",
    );
  }

  return result;
}

export async function createFreeRepairAssistantMessage(
  chatId: string,
  repairMessageId: string,
  text: string,
  files: RawGeneratedFile[],
  options?: { generationRunId?: string },
) {
  const session = await getCurrentSession();

  if (!session) {
    throw new Error("You must be signed in to save a repair");
  }

  const prisma = getPrisma();
  const chat = await findOwnedProjectWithMessages(chatId, session.user.id);
  if (!chat) notFound();

  const repairMessage = chat.messages.find(
    (message) => message.id === repairMessageId,
  );
  const repairMetadata = repairMessage?.files as
    | {
        kind?: string;
        chargeCredits?: boolean;
        usedAt?: string | null;
        rootGenerationRunId?: string;
      }
    | null
    | undefined;
  const isPreviewRepair =
    repairMetadata?.kind === "preview_repair" ||
    repairMetadata?.kind === "preview_repair_request";
  const contractRepair = readContractRepairMetadata(repairMessage?.files);

  if (
    !repairMessage ||
    repairMessage.role !== "user" ||
    (!isPreviewRepair && !contractRepair) ||
    repairMetadata?.chargeCredits !== false ||
    repairMetadata?.usedAt
  ) {
    throw new Error("Repair request is not eligible for a free repair");
  }

  const maxPosition =
    chat.messages.length > 0
      ? Math.max(...chat.messages.map((message) => message.position))
      : 0;
  const normalizedFiles = normalizeGeneratedFiles(files);
  const assistantHasFiles = normalizedFiles.length > 0;
  const finalizedCode =
    assistantHasFiles && text.trim()
      ? finalizeGeneratedCodeFromText(text)
      : null;
  const designScores =
    finalizedCode?.ok && finalizedCode.designScores
      ? finalizedCode.designScores
      : null;
  if (assistantHasFiles) {
    const diagnostics = await getGeneratedAppContractDiagnostics(
      prisma,
      chatId,
      normalizedFiles,
    );
    if (diagnostics.length > 0) {
      if (options?.generationRunId) {
        await prisma.generationRun.updateMany({
          where: {
            id: options.generationRunId,
            chatId,
            userId: session.user.id,
          },
          data: {
            status: "recoverable",
            phase: "validation_repair",
            label: "Fixing generated app",
            errorMessage: "Generated app did not pass its required contract",
          },
        });
      }
      throw contractViolationError(diagnostics);
    }
  }
  const newMessage = await prisma.$transaction(async (tx) => {
    const rootRun = contractRepair
      ? await tx.generationRun.findFirst({
          where: {
            id: contractRepair.rootGenerationRunId,
            chatId,
            userId: session.user.id,
          },
          select: { id: true, messageId: true, creditHoldId: true },
        })
      : null;
    if (contractRepair && !rootRun) {
      throw new Error("Original generation run was not found");
    }
    const rootMessage = rootRun
      ? await tx.message.findFirst({
          where: { id: rootRun.messageId, chatId },
          select: { files: true },
        })
      : null;
    const rootMessageMetadata = rootMessage?.files as
      | { kind?: string; chargeCredits?: boolean }
      | null
      | undefined;
    const rootWasFreeRepair =
      (rootMessageMetadata?.kind === "preview_repair" ||
        rootMessageMetadata?.kind === "preview_repair_request") &&
      rootMessageMetadata.chargeCredits === false;

    const newMessage = await tx.message.create({
      data: {
        role: "assistant",
        content: text,
        files: assistantHasFiles
          ? JSON.parse(JSON.stringify(normalizedFiles))
          : null,
        position: maxPosition + 1,
        chatId,
        versionKind: "repair",
        changeSummary: contractRepair
          ? "Completed generated app contract"
          : "Repaired preview",
        ...(designScores
          ? { designScores: JSON.parse(JSON.stringify(designScores)) }
          : {}),
      },
    });

    await tx.message.update({
      where: { id: repairMessageId },
      data: {
        files: {
          ...repairMetadata,
          usedAt: new Date().toISOString(),
        },
      },
    });

    if (assistantHasFiles) {
      await tx.chat.update({
        where: { id: chatId },
        data: { hasCode: true },
      });
    }

    if (contractRepair && !rootWasFreeRepair) {
      const creditCheck = await consumeCreditsForGeneration({
        client: tx,
        userId: session.user.id,
        modelId: chat.model,
        chatId,
        messageId: newMessage.id,
        description: `AI generation - ${chat.model}`,
        phase: "validation_repair",
        status: "completed",
        creditHoldId: rootRun?.creditHoldId ?? undefined,
        generatedText: text,
      });
      if (!creditCheck.success) {
        throw new Error(
          creditCheck.error === "INSUFFICIENT_CREDITS"
            ? "INSUFFICIENT_CREDITS"
            : "CREDIT_CHECK_FAILED",
        );
      }
    } else {
      await tx.generationLog.create({
        data: {
          userId: session.user.id,
          modelId: chat.model,
          creditsUsed: 0,
          estimatedCredits: getModelCreditHoldCost(chat.model),
          actualCredits: 0,
          refundedCredits: 0,
          reason: "Free preview repair",
          phase: "preview_repair",
          status: "free_repair",
          chatId,
          messageId: newMessage.id,
        },
      });
    }

    if (contractRepair && rootRun) {
      await tx.generationRun.updateMany({
        where: { id: rootRun.id, chatId, userId: session.user.id },
        data: {
          status: "completed",
          phase: "completed",
          label: "Generated app ready",
          assistantMessageId: newMessage.id,
          errorMessage: null,
          completedAt: new Date(),
        },
      });
    }

    if (
      options?.generationRunId &&
      options.generationRunId !== contractRepair?.rootGenerationRunId
    ) {
      await tx.generationRun.updateMany({
        where: {
          id: options.generationRunId,
          chatId,
          userId: session.user.id,
          status: { in: ["running", "recoverable"] },
        },
        data: {
          status: "completed",
          assistantMessageId: newMessage.id,
          completedAt: new Date(),
          phase: "completed",
          label: contractRepair ? "Generated app ready" : "Repaired preview",
          errorMessage: null,
        },
      });
    }

    return newMessage;
  });

  scheduleFollowUpPrompts({
    prisma,
    messageId: newMessage.id,
    chat,
    assistantContent: text,
    files: normalizedFiles,
  });

  return newMessage;
}

export async function restoreVersionAsCheckpoint({
  chatId,
  sourceMessageId,
  oldVersion,
  newVersion,
}: {
  chatId: string;
  sourceMessageId: string;
  oldVersion: number;
  newVersion: number;
}) {
  const session = await getCurrentSession();

  if (!session) {
    throw new Error("You must be signed in to restore versions");
  }

  const prisma = getPrisma();
  const chat = await findOwnedProjectWithMessages(chatId, session.user.id);
  if (!chat) notFound();

  const sourceMessage = chat.messages.find(
    (message) => message.id === sourceMessageId,
  );

  if (!sourceMessage || sourceMessage.role !== "assistant") {
    throw new Error("Restore source version was not found");
  }

  const restoredFiles = getMessageGeneratedFiles(sourceMessage);

  if (restoredFiles.length === 0) {
    throw new Error("Restore source version has no files");
  }

  const maxPosition =
    chat.messages.length > 0
      ? Math.max(...chat.messages.map((message) => message.position))
      : 0;
  const explanation = `Version ${newVersion} was created by restoring version ${oldVersion}.`;
  const content = `${explanation}\n\n${formatGeneratedFilesMarkdown(restoredFiles)}`;
  const newMessage = await prisma.message.create({
    data: {
      role: "assistant",
      content,
      files: JSON.parse(JSON.stringify(restoredFiles)),
      position: maxPosition + 1,
      chatId,
      versionKind: "restore",
      changeSummary: `Restored v${oldVersion}`,
    },
  });

  scheduleFollowUpPrompts({
    prisma,
    messageId: newMessage.id,
    chat,
    assistantContent: content,
    files: restoredFiles,
  });

  await prisma.chat.update({
    where: { id: chatId },
    data: { hasCode: true },
  });

  return newMessage;
}

export async function restoreSelectedFilesAsCheckpoint({
  chatId,
  sourceMessageId,
  paths,
}: {
  chatId: string;
  sourceMessageId: string;
  paths: string[];
}) {
  const session = await getCurrentSession();
  if (!session) throw new Error("You must be signed in to restore files");

  const prisma = getPrisma();
  const chat = await findOwnedProjectWithMessages(chatId, session.user.id);
  if (!chat) notFound();

  const source = chat.messages.find(
    (message) => message.id === sourceMessageId,
  );
  const latest = chat.messages
    .filter(
      (message) =>
        message.role === "assistant" &&
        getMessageGeneratedFiles(message).length > 0,
    )
    .sort((a, b) => b.position - a.position)[0];
  if (!source || source.role !== "assistant" || !latest) {
    throw new Error("A source and current version are required");
  }

  const requestedPaths = new Set(
    paths.map((path) => path.trim()).filter(Boolean),
  );
  if (requestedPaths.size === 0 || requestedPaths.size > 50) {
    throw new Error("Select between 1 and 50 files to restore");
  }
  const sourceFiles = new Map(
    getMessageGeneratedFiles(source).map((file) => [file.path, file]),
  );
  const restoredFiles = new Map(
    getMessageGeneratedFiles(latest).map((file) => [file.path, file]),
  );
  for (const path of requestedPaths) {
    const sourceFile = sourceFiles.get(path);
    if (sourceFile) restoredFiles.set(path, sourceFile);
    else restoredFiles.delete(path);
  }

  const files = normalizeGeneratedFiles(Array.from(restoredFiles.values()));
  const maxPosition = Math.max(
    ...chat.messages.map((message) => message.position),
  );
  const selectedPaths = Array.from(requestedPaths);
  const explanation = `Restored ${selectedPaths.length} file${selectedPaths.length === 1 ? "" : "s"} from an earlier checkpoint without changing other current files.`;
  const content = `${explanation}\n\n${formatGeneratedFilesMarkdown(files)}`;
  const newMessage = await prisma.message.create({
    data: {
      role: "assistant",
      content,
      files: JSON.parse(JSON.stringify(files)),
      position: maxPosition + 1,
      chatId,
      versionKind: "selective_restore",
      changeSummary: `Restored ${selectedPaths.join(", ").slice(0, 64)}`,
    },
  });
  await prisma.chat.update({ where: { id: chatId }, data: { hasCode: true } });
  return newMessage;
}
